    .modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 999;
    }

    @keyframes fadeIn {
    from { opacity: 0; transform: scale(0.95); }
    to { opacity: 1; transform: scale(1); }
    }

    .modal-close {
    position: absolute;
    top: 10px;
    right: 10px;
    background: #000000;
    color: white;
    border: none;
    border-radius: 20%;
    width: 30px;
    height: 30px;
    font-size: 1rem;
    cursor: pointer;
    padding: 0.5%;
    }

    .modal-close:hover {
    background: #444;
}

    .modal-container {
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: rgb(142, 138, 133);
    border-radius: 10px;
    border-color: #1C3ABD;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
    animation: fadeIn 0.5s ease-in-out forwards;
    }

    .modal-content {
    display: flex;
    justify-content: center;
    align-items: center;
    transform-origin: center;
    padding: 15px;
    }

